def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find a full-width or full-height nonzero separator.
    split = None
    for r, row in enumerate(grid):
        if row and row[0] != 0 and all(x == row[0] for x in row):
            split = ("h", r)
            break
    if split is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if vals[0] != 0 and all(x == vals[0] for x in vals):
                split = ("v", c)
                break
    if split is None:
        raise ValueError("separator not found")
    axis, k = split
    if axis == "h":
        a, b = grid[:k], grid[k+1:]
        n = min(len(a), len(b))
        return [[2 if a[r][c] != 0 and b[r][c] != 0 else 0 for c in range(w)] for r in range(n)]
    a, b = [row[:k] for row in grid], [row[k+1:] for row in grid]
    n = min(len(a[0]), len(b[0]))
    return [[2 if a[r][c] != 0 and b[r][c] != 0 else 0 for c in range(n)] for r in range(h)]

